-- Data (hand-written, P-027): admins and their argon2id password hashes move to Better Auth.
-- The ids stay the same, so audit_log.admin_id, bans and player_notes keep resolving. Disabled
-- admins become banned users (Better Auth refuses their sessions) and keep disabled_at.
INSERT INTO "auth_users" ("id", "name", "email", "email_verified", "created_at", "updated_at", "role", "banned", "ban_reason", "disabled_at")
SELECT "id", split_part("email", '@', 1), "email", true, "created_at", CURRENT_TIMESTAMP, "role"::text,
       "disabled_at" IS NOT NULL, CASE WHEN "disabled_at" IS NOT NULL THEN 'disabled' END, "disabled_at"
FROM "admin_users";

INSERT INTO "auth_accounts" ("account_id", "provider_id", "user_id", "password", "created_at", "updated_at")
SELECT "id"::text, 'credential', "id", "password_hash", "created_at", CURRENT_TIMESTAMP
FROM "admin_users";

